  const noWait = { sleep: async () => {}, random: () => 0 };

  // A fake client whose create() throws each queued error in turn before
  // returning a valid completion; records the endpoint URL per call.
  function flakyClient(failures: Record<string, unknown[]>) {
    const calls: string[] = [];
    const factory = (ep: LLMEndpoint) =>
      ({
        chat: {
          completions: {
            create: async () => {
              calls.push(ep.baseURL);
              const next = failures[ep.baseURL]?.shift();
              if (next) throw next;
              return {
                choices: [
                  { message: { content: `translated via ${ep.baseURL}` } },
                ],
              };
            },
          },
        },
      }) as unknown as Pick<OpenAI, 'chat'>;
    return { calls, factory };
  }

  it('retries a 5xx then succeeds within one endpoint call', async () => {
    const { calls, factory } = flakyClient({
      'https://p': [
        new OpenAI.APIError(500, undefined, 'boom', undefined),
        new OpenAI.APIError(500, undefined, 'boom', undefined),
      ],
    });
    const t = new OpenAICompatTranslator(
      endpoint('https://p'),
      endpoint('https://f'),
      factory,
      noWait,
    );
    const out = await t.translate(segment, [], 'vi');
    expect(out).toBe('translated via https://p');
    expect(calls).toEqual(['https://p', 'https://p', 'https://p']);
  });

  it('fails a 4xx immediately without retrying', async () => {
    const { calls, factory } = flakyClient({
      'https://p': [new OpenAI.APIError(400, undefined, 'bad', undefined)],
    });
    const t = new OpenAICompatTranslator(
      endpoint('https://p'),
      undefined,
      factory,
      noWait,
    );
    await expect(t.translate(segment, [], 'vi')).rejects.toBeInstanceOf(
      TranslationError,
    );
    expect(calls).toEqual(['https://p']);
  });

  it('exhausts 3 attempts on persistent 5xx with no fallback', async () => {
    const { calls, factory } = flakyClient({
      'https://p': [
        new OpenAI.APIError(503, undefined, 'down', undefined),
        new OpenAI.APIError(503, undefined, 'down', undefined),
        new OpenAI.APIError(503, undefined, 'down', undefined),
        new OpenAI.APIError(503, undefined, 'down', undefined),
      ],
    });
    const t = new OpenAICompatTranslator(
      endpoint('https://p'),
      undefined,
      factory,
      noWait,
    );
    await expect(t.translate(segment, [], 'vi')).rejects.toBeInstanceOf(
      TranslationError,
    );
    expect(calls).toEqual(['https://p', 'https://p', 'https://p']);
  });

  it('retries a connection error then succeeds', async () => {
    const { calls, factory } = flakyClient({
      'https://p': [new OpenAI.APIConnectionError({ message: 'reset' })],
    });
    const t = new OpenAICompatTranslator(
      endpoint('https://p'),
      undefined,
      factory,
      noWait,
    );
    const out = await t.translate(segment, [], 'vi');
    expect(out).toBe('translated via https://p');
    expect(calls).toEqual(['https://p', 'https://p']);
  });

  it('still honors the fallback after primary retry exhaustion', async () => {
    const { calls, factory } = flakyClient({
      'https://p': [
        new OpenAI.APIError(500, undefined, 'down', undefined),
        new OpenAI.APIError(500, undefined, 'down', undefined),
        new OpenAI.APIError(500, undefined, 'down', undefined),
        new OpenAI.APIError(500, undefined, 'down', undefined),
      ],
    });
    const t = new OpenAICompatTranslator(
      endpoint('https://p'),
      endpoint('https://f'),
      factory,
      noWait,
    );
    const out = await t.translate(segment, [], 'vi');
    expect(out).toBe('translated via https://f');
    expect(calls).toEqual(['https://p', 'https://p', 'https://p', 'https://f']);
  });
});

